    # WHY: performance work needs a baseline before changing behavior. This proof
    # keeps the C1 record cheap and repeatable so future local-history or typing
    # changes can compare real endpoint timings instead of guessing.
    require "$LATENCY_BASELINE_PROOF" 'PHONE_LATENCY_OUTPUT' "latency proof must write a reusable baseline artifact"
    require "$LATENCY_BASELINE_PROOF" 'mantis-phone-control-server' "latency proof must default to the live Mantis control server when installed"
    require "$LATENCY_BASELINE_PROOF" '.mantis/phone-terminal/web-control-token' "latency proof must prefer the live Mantis web token before the legacy token path"
    require "$LATENCY_BASELINE_PROOF" 'tabs_light' "latency proof must include the Active picker's fast light tabs endpoint"
    require "$LATENCY_BASELINE_PROOF" 'active_window_metadata' "latency proof must include the cheap active-window metadata endpoint"
    require "$LATENCY_BASELINE_PROOF" '%{http_code} %{time_total}' "latency proof must measure status and timing in one request"
    require "$LATENCY_BASELINE_PROOF" 'scrollback_chunk_80' "latency proof must include the new C4 chunk endpoint"
    require "$LATENCY_BASELINE_PROOF" 'web_config_token' "latency proof must include tokenized browser config"
    require "$LATENCY_BASELINE_PROOF" 'Phone latency baseline proof passed' "latency proof must have an explicit success receipt"
else
    echo "Phone plan regression guard failed: missing latency baseline proof script" >&2
    echo "File: $LATENCY_BASELINE_PROOF" >&2
    exit 1
fi

if [ -f "$PHONE_HOST_KEEPALIVE" ]; then
    # WHY: the 2026-06-17 phone outage proved ttyd can remain alive while the
    # control API is gone. Host keepalive must probe the actual phone-facing
    # control payloads and tmux session, then use the idempotent Mantis start
    # path instead of killing tmux or silently restarting user work.
    require "$PHONE_HOST_KEEPALIVE" 'CONTROL_TABS_URL' "host keepalive must prove the fast Active picker payload, not only the ttyd socket"
    require "$PHONE_HOST_KEEPALIVE" 'CONTROL_ACTIVE_URL' "host keepalive must prove active-window metadata, not only the ttyd socket"
    require "$PHONE_HOST_KEEPALIVE" 'tmux has-session -t "$TMUX_SESSION"' "host keepalive must prove main_phone still exists"
    require "$PHONE_HOST_KEEPALIVE" 'mantis}" phone start-host' "host keepalive must repair through the idempotent Mantis start-host path"
    require "$PHONE_HOST_KEEPALIVE" 'instead of killing tmux' "host keepalive WHY comment must preserve the no-tmux-kill boundary"
    require "$PHONE_HOST_KEEPALIVE" 'startup' "host keepalive must support reboot/startup cron mode"
    require "$PHONE_HOST_KEEPALIVE" '--startup' "host keepalive must support explicit startup cron mode"
else
    echo "Phone plan regression guard failed: missing host keepalive script" >&2
    echo "File: $PHONE_HOST_KEEPALIVE" >&2
    exit 1
fi

if [ -f "$APK_RELEASE_SCRIPT" ]; then
    # WHY: Mantis Remote APK updates live in the separate WEzTerm Android repo,
    # not the private Mantis bundle repo. The release lane must wait for clean,
    # pushed source before tagging and uploading the APK asset, or GitHub's
    # latest/download URL can lag behind the phone build installed locally.
    require "$APK_RELEASE_SCRIPT" 'waiting for WEzTerm source autopush before APK release' "APK release cron must wait for clean source before publishing"
    require "$APK_RELEASE_SCRIPT" 'origin/main to match local HEAD' "APK release cron must prove GitHub has the source commit before tagging"
    require "$APK_RELEASE_SCRIPT" 'gh release create "$tag" "$apk#WEzterm.apk"' "APK release cron must create the GitHub release asset"
    require "$APK_RELEASE_SCRIPT" 'gh release upload "$tag" "$apk#WEzterm.apk"' "APK release cron must refresh an existing GitHub release asset safely"
    require "$APK_RELEASE_SCRIPT" 'Stop maps to one desktop Escape' "APK release notes must preserve direct Stop behavior"
    require "$APK_RELEASE_SCRIPT" 'Enter / IME action submits through the same pinned path as Send' "APK release notes must preserve direct Enter behavior"
else
    echo "Phone plan regression guard failed: missing WEzTerm APK release script" >&2
    echo "File: $APK_RELEASE_SCRIPT" >&2
    exit 1
fi

if [ -f "$LOCAL_HISTORY_UI_PROOF" ]; then
    # WHY: C5 is only complete if the installed APK exposes the native local
    # history viewer through the real Scroll menu and searches cached rows
    # without entering tmux copy-mode or moving the active session. Source grep
    # alone would miss the exact class of phone-only regressions this plan is
    # protecting against.
    require "$LOCAL_HISTORY_UI_PROOF" 'Local history search' "local history UI proof must open the Scroll menu item"
    require "$LOCAL_HISTORY_UI_PROOF" 'C5LOCALHISTORYPROOF_120' "local history UI proof must read disposable cached history rows"
    require "$LOCAL_HISTORY_UI_PROOF" 'No cached history matches' "local history UI proof must prove local search/filter behavior"
    require "$LOCAL_HISTORY_UI_PROOF" 'endpoint changed active window' "local history UI proof must fail if the chunk endpoint selects windows"
    require "$LOCAL_HISTORY_UI_PROOF" 'Phone local history UI proof passed' "local history UI proof must have an explicit success receipt"
else
    echo "Phone plan regression guard failed: missing local history UI proof script" >&2
    echo "File: $LOCAL_HISTORY_UI_PROOF" >&2
    exit 1
fi

# WHY: Bash `-n` cannot parse embedded heredoc Python. The toolbar geometry
# proof is the guard that catches hidden composer rows and giant keyboard blanks;
# if its Python has bad indentation, the proof harness fails before it can protect
# the user-facing phone UI. Compile that heredoc here so harness regressions are
# caught before APK build or install.
python3 - "$ROOT/scripts/prove-phone-menu-ui.sh" <<'PY'
import pathlib
import sys

path = pathlib.Path(sys.argv[1])
lines = path.read_text(encoding="utf-8").splitlines()
marker = '    python3 - "$DUMP_LOCAL" "$ime_state" <<\'PY\''
try:
    start = lines.index(marker) + 1
except ValueError as exc:
    raise SystemExit(f"Phone plan regression guard failed: missing toolbar geometry Python heredoc in {path}") from exc
body = []
for line in lines[start:]:
    if line == "PY":
        break
    body.append(line)
else:
    raise SystemExit(f"Phone plan regression guard failed: unterminated toolbar geometry Python heredoc in {path}")
compile("\n".join(body) + "\n", f"{path}:assert_terminal_toolbar_geometry", "exec")
PY

echo "Phone plan regression guard passed"
